local Players=game:GetService("Players") local RunService=game:GetService("RunService") local LocalPlayer=Players.LocalPlayer local Camera=workspace.CurrentCamera local Config={Speed=50,JumpPower=100,Aimbot=false,ESP=true,WallCheck=false,TeamCheck=true} local AimbotKey=Enum.KeyCode.E local EspColor=Color3.fromRGB(255,0,0) local function CreateESP(player) if player==LocalPlayer then return end local Box=Drawing.new("Square") Box.Visible=false Box.Color=EspColor Box.Thickness=1 Box.Filled=false local Name=Drawing.new("Text") Name.Visible=false Name.Color=Color3.fromRGB(255,255,255) Name.Size=16 Name.Center=true Name.Outline=true local function Update() if not player.Character or not player.Character:FindFirstChild("HumanoidRootPart") then Box.Visible=false Name.Visible=false return end local Root=player.Character.HumanoidRootPart local Pos,OnScreen=Camera:WorldToViewportPoint(Root.Position) if not OnScreen then Box.Visible=false Name.Visible=false return end local Distance=(Camera.CFrame.Position-Root.Position).Magnitude local Head=Root.Position+Vector3.new(0,1.5,0) local Feet=Root.Position-Vector3.new(0,3,0) local HeadPos=Head local FeetPos=Feet local HeadScreen=Camera:WorldToViewportPoint(HeadPos) local FeetScreen=Camera:WorldToViewportPoint(FeetPos) local Height=math.abs(HeadScreen.Y-FeetScreen.Y) local Width=Height/2 Box.Size=Vector2.new(Width,Height) Box.Position=Vector2.new(Pos.X-Width/2,Pos.Y-Height/2) Box.Visible=Config.ESP Name.Text=player.Name.." ["..math.floor(Distance).."m]" Name.Position=Vector2.new(Pos.X,Pos.Y-Height/2-20) Name.Visible=Config.ESP end RunService.RenderStepped:Connect(Update) end for _,v in pairs(Players:GetPlayers()) do CreateESP(v) end Players.PlayerAdded:Connect(CreateESP) local function Aimbot() if not Config.Aimbot then return end local Closest=math.huge local Target=nil for _,v in pairs(Players:GetPlayers()) do if v~=LocalPlayer and v.Character and v.Character:FindFirstChild("Head") then local Head=v.Character.Head local Pos,OnScreen=Camera:WorldToViewportPoint(Head.Position) if OnScreen then local Dist=(Camera.CFrame.Position-Head.Position).Magnitude if Dist<Closest then Closest=Dist Target=Head end end end end if Target then Camera.CFrame=Camera.CFrame:Lerp(CFrame.new(Camera.CFrame.Position,Target.Position),0.5) end end RunService.RenderStepped:Connect(Aimbot) game:GetService("UserInputService").InputBegan:Connect(function(input,gpe) if gpe then return end if input.KeyCode==Enum.KeyCode.RightShift then Config.Aimbot=not Config.Aimbot print("Aimbot: "..tostring(Config.Aimbot)) end end)